string Note(int prozent)
{
    if (prozent >= 90) return "Sehr gut";
    if (prozent >= 80) return "Gut";
    if (prozent >= 65) return "Befriedigend";
    if (prozent >= 50) return "Genügend";
    return "Nicht genügend";
}

int fehler = 0;

Pruefe("95 %", "Sehr gut", Note(95));
Pruefe("80 %", "Gut", Note(80));
Pruefe("49 %", "Nicht genügend", Note(49));
Console.WriteLine($"{fehler} Fehler");

void Pruefe(string name, string erwartet,
            string tatsaechlich)
{
    if (erwartet == tatsaechlich)
    {
        Console.WriteLine($"OK     {name}");
    }
    else
    {
        Console.WriteLine($"FEHLER {name}: " +
            $"erwartet {erwartet}, " +
            $"war {tatsaechlich}");
        fehler++;
    }
}
