using System.Diagnostics;

int[] a = { 1, 2, 3 };
int[] leer = { };
int[] b = { -4, 4 };

Debug.Assert(Summe(a) == 6);
Debug.Assert(Summe(leer) == 0, "leer");
Debug.Assert(Summe(b) == 0, "negativ");
Console.WriteLine("Alle Tests bestanden");

int Summe(int[] zahlen)
{
    int s = 0;
    foreach (int z in zahlen)
    {
        s += z;
    }
    return s;
}
